def update(self, iterable):
        """Add key-value pairs from *iterable* to this relationship.

        ``iterable`` may be another :class:`ManyToMany`, a
        dictionary-like object, or an iterable of ``(key, value)`` pairs.
        Existing relationships are preserved.
        """
        if isinstance(iterable, ManyToMany):
            for key, values in iterable.data.items():
                for value in values:
                    self.add(key, value)
            return

        if hasattr(iterable, 'keys'):
            iterable = ((key, iterable[key]) for key in iterable.keys())

        for key, value in iterable:
            self.add(key, value)

def make_safe_absolute_uri(base, rel=None):
    """Join a base URI and relative URI, returning a safe absolute URI."""

    if rel is None:
        uri = base
    else:
        uri = _urljoin(base, rel)

    if not uri:
        return uri

    try:
        uri = convert_to_idn(uri)
        parts = urllib.parse.urlsplit(uri)
    except (UnicodeError, ValueError):
        return ''

    # Reject URI schemes that are not explicitly allowed. Relative URIs are
    # retained when they cannot be resolved because the base is empty.
    scheme = parts.scheme.lower()
    if scheme and ACCEPTABLE_URI_SCHEMES and scheme not in ACCEPTABLE_URI_SCHEMES:
        return ''

    # Escape characters that commonly make an otherwise valid URI unsafe.
    if scheme in ('http', 'https'):
        uri = uri.replace(' ', '%20')

    uri = (
        uri.replace('<', '%3C')
        .replace('>', '%3E')
        .replace('"', '%22')
        .replace("'", '%27')
    )

    return uri

