def join(*paths):
    # type: (Text) -> Text
    """Join multiple path components into a single normalized path."""
    if not paths:
        return ""

    # Preserve a leading slash from the first path, while treating leading
    # and trailing separators in subsequent components as delimiters.
    absolute = paths[0].startswith("/")
    components = [paths[0].strip("/")]

    for path in paths[1:]:
        components.append(path.strip("/"))

    joined = "/".join(component for component in components if component)
    if absolute:
        joined = "/" + joined

    return normpath(joined or ("/" if absolute else ""))

def join(*paths):
    """Join multiple PyFilesystem paths into a single path.

    If an absolute path is encountered, all preceding path segments are
    discarded and joining continues from that absolute path.
    """
    if not paths:
        return ""

    path = paths[0]
    for component in paths[1:]:
        if component.startswith("/"):
            path = component
        else:
            path = path.rstrip("/") + "/" + component

    return normpath(path)

def join(*paths):
    # type: (Text) -> Text
    """Join path components and normalize the resulting path."""
    if not paths:
        return ""

    combined = ""
    for path in paths:
        if not path:
            continue

        if path.startswith("/"):
            # Absolute paths discard all previously joined components.
            combined = path
        elif not combined:
            combined = path
        elif combined.endswith("/"):
            combined += path
        else:
            combined += "/" + path

    if not combined:
        return ""

    return normpath(combined)

def join(*paths):
    """Join path components into a normalized path.

    If any component is absolute, all preceding components are discarded.
    The result is normalized using :func:`normpath`.
    """
    if not paths:
        return ""

    joined = paths[0]

    for path in paths[1:]:
        if isabs(path):
            joined = path
        elif joined:
            joined = joined.rstrip("/") + "/" + path
        else:
            joined = path

    return normpath(joined)

